frappe.ui.form.on('BIR Cash Receipt Journal', {
    generate_report: function(frm) {
        if (!frm.doc.company || !frm.doc.from_date || !frm.doc.to_date) {
            frappe.throw(__('Please select Company, From Date, and To Date first.'));
            return;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Sales Invoice',
                filters: {
                    company: frm.doc.company,
                    posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]],
                    docstatus: 1
                },
                fields: ['name', 'customer_name', 'posting_date', 'net_total', 'grand_total', 'status', 'total_taxes_and_charges', 'tax_id', 'address_display', 'remarks', 'update_stock'],
                limit_page_length: 500,
                order_by: 'posting_date asc, name asc'
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    frm.clear_table('journal_entries');
                    frm.clear_table('account_summary');

                    let invoices = r.message.map(si => si.name);

                    // Fetch payment dates in bulk from Payment Ledger
                    frappe.call({
                        method: 'frappe.client.get_list',
                        args: {
                            doctype: 'Payment Ledger Entry',
                            filters: {
                                against_voucher_no: ['in', invoices],
                                company: frm.doc.company,
                                delinked: 0
                            },
                            fields: ['against_voucher_no', 'posting_date'],
                            limit_page_length: 5000
                        },
                        callback: function(ple_res) {
                            let payment_dates = {};
                            if (ple_res.message) {
                                ple_res.message.forEach(ple => {
                                    payment_dates[ple.against_voucher_no] = ple.posting_date;
                                });
                            }

                            let sum_vatable = 0;
                            let sum_vat = 0;
                            let sum_zero = 0;
                            let sum_exempt = 0;
                            let sum_total = 0;
                            let sum_wtax = 0;
                            let sum_net_cash = 0;

                            // Map invoice records to the child table
                            r.message.forEach(si => {
                                let row = frm.add_child('journal_entries');
                                row.date = si.posting_date || '';
                                row.payor = si.customer_name;
                                row.tin = si.tax_id || '';

                                // Clean address HTML into single line
                                row.address = (si.address_display || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

                                row.invoice_no = si.name;
                                row.rendered = si.update_stock ? 'Goods' : 'Services';
                                row.discount_type = 'NONE';
                                row.discount_amount = 0;

                                // Financial Splits
                                let taxes = si.total_taxes_and_charges || 0;
                                if (taxes > 0) {
                                    row.vatable = si.net_total || 0;
                                    row.output_vat = taxes;
                                    row.zero_rated = 0;
                                    row.vat_exempt = 0;

                                    sum_vatable += si.net_total || 0;
                                    sum_vat += taxes;
                                } else {
                                    row.vatable = 0;
                                    row.output_vat = 0;
                                    row.zero_rated = 0;
                                    row.vat_exempt = si.net_total || 0;

                                    sum_exempt += si.net_total || 0;
                                }

                                row.total = si.grand_total || 0;
                                row.w_tax = 0;
                                row.net_cash = si.grand_total || 0;
                                row.note = '';
                                row.status = si.status.toUpperCase();

                                sum_total += si.grand_total || 0;
                                sum_net_cash += si.grand_total || 0;

                                // Payment Date lookup
                                let raw_pay_date = payment_dates[si.name];
                                if (raw_pay_date) {
                                    row.payment_date = frappe.datetime.str_to_user(raw_pay_date);
                                } else {
                                    row.payment_date = '-';
                                }
                            });

                            // Add Account Summary Rows
                            let sum1 = frm.add_child('account_summary');
                            sum1.account_title = 'Accounts Receivable';
                            sum1.debit = sum_total;
                            sum1.credit = 0;

                            let sum2 = frm.add_child('account_summary');
                            sum2.account_title = 'Creditable Withholding Tax';
                            sum2.debit = sum_wtax;
                            sum2.credit = 0;

                            let sum3 = frm.add_child('account_summary');
                            sum3.account_title = 'Sales';
                            sum3.debit = 0;
                            sum3.credit = sum_vatable + sum_zero + sum_exempt;

                            let sum4 = frm.add_child('account_summary');
                            sum4.account_title = 'Output VAT Payable';
                            sum4.debit = 0;
                            sum4.credit = sum_vat;

                            let sum_tot = frm.add_child('account_summary');
                            sum_tot.account_title = 'Total';
                            sum_tot.debit = sum1.debit + sum2.debit;
                            sum_tot.credit = sum3.credit + sum4.credit;

                            frm.refresh_field('journal_entries');
                            frm.refresh_field('account_summary');
                            frappe.show_alert({message: __('Cash Receipt journal generated successfully!'), indicator: 'green'});
                        }
                    });
                } else {
                    frappe.msgprint(__('No Sales Invoices found for this period.'));
                }
            }
        });
    }
});

frappe.ui.form.on('BIR Form 2307', {
    generate_report: function(frm) {
        if (!frm.doc.company || !frm.doc.from_date || !frm.doc.to_date || !frm.doc.party) {
            frappe.throw(__('Please select Company, Date range, Party Type and Party first.'));
            return;
        }

        // 1. Fetch Company details
        let get_company_details = function() {
            return new Promise((resolve) => {
                frappe.call({
                    method: 'frappe.client.get',
                    args: { doctype: 'Company', name: frm.doc.company },
                    callback: function(r) { resolve(r.message || {}); }
                });
            });
        };

        // 2. Fetch Party details
        let get_party_details = function() {
            return new Promise((resolve) => {
                frappe.call({
                    method: 'frappe.client.get',
                    args: { doctype: frm.doc.party_type, name: frm.doc.party },
                    callback: function(r) { resolve(r.message || {}); }
                });
            });
        };

        // 3. Fetch Invoices list
        let get_invoices = function() {
            return new Promise((resolve) => {
                let dt = frm.doc.party_type === 'Customer' ? 'Sales Invoice' : 'Purchase Invoice';
                let party_field = frm.doc.party_type === 'Customer' ? 'customer' : 'supplier';
                let filters = {
                    company: frm.doc.company,
                    posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]],
                    docstatus: 1
                };
                filters[party_field] = frm.doc.party;

                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: dt,
                        filters: filters,
                        fields: ['name', 'posting_date', 'net_total'],
                        limit_page_length: 5000
                    },
                    callback: function(r) { resolve(r.message || []); }
                });
            });
        };

        Promise.all([get_company_details(), get_party_details(), get_invoices()]).then(results => {
            let comp = results[0];
            let party = results[1];
            let invoices = results[2];

            // Set Payee and Payor info
            let clean_address = function(addr) {
                return (addr || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
            };

            if (frm.doc.party_type === 'Customer') {
                // Payee is Company, Payor is Customer
                frm.set_value('payee_name', comp.company_name);
                frm.set_value('payee_tin', comp.tax_id || '314-579-230-000');
                frm.set_value('payee_address', clean_address(comp.billing_address || 'Davao City'));
                frm.set_value('payee_zip', '8000');

                frm.set_value('payor_name', party.customer_name);
                frm.set_value('payor_tin', party.tax_id || '');
                frm.set_value('payor_address', clean_address(party.primary_address || ''));
                frm.set_value('payor_zip', '8000');
            } else {
                // Payee is Supplier, Payor is Company
                frm.set_value('payee_name', party.supplier_name);
                frm.set_value('payee_tin', party.tax_id || '');
                frm.set_value('payee_address', clean_address(party.primary_address || ''));
                frm.set_value('payee_zip', '8000');

                frm.set_value('payor_name', comp.company_name);
                frm.set_value('payor_tin', comp.tax_id || '314-579-230-000');
                frm.set_value('payor_address', clean_address(comp.billing_address || 'Davao City'));
                frm.set_value('payor_zip', '8000');
            }

            if (invoices.length === 0) {
                frm.clear_table('withholding_details');
                frm.refresh_field('withholding_details');
                frappe.show_alert({message: __('No invoices found in this period.'), indicator: 'orange'});
                return;
            }

            let inv_names = invoices.map(i => i.name);
            let inv_map = {};
            invoices.forEach(i => { inv_map[i.name] = i; });

            // 4. Fetch GL Entries for withholding
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'GL Entry',
                    filters: { voucher_no: ['in', inv_names] },
                    fields: ['voucher_no', 'account', 'debit', 'credit', 'posting_date'],
                    limit_page_length: 5000
                },
                callback: function(gl_res) {
                    let grouped_data = {};
                    let start_date = frappe.datetime.str_to_obj(frm.doc.from_date);
                    let start_month = start_date.getMonth() + 1; // 1-12

                    if (gl_res.message) {
                        gl_res.message.forEach(gl => {
                            let head = (gl.account || '').toLowerCase();
                            if (head.includes('ewt') || head.includes('withholding') || head.includes('creditable') || head.includes('tds')) {
                                let inv = inv_map[gl.voucher_no];
                                if (!inv) return;

                                let amt = Math.abs((gl.debit || 0) - (gl.credit || 0));
                                let rate = Math.round((amt / (inv.net_total || 1)) * 100 * 100) / 100;

                                // Determine ATC code and description based on rate
                                let atc = 'WI150';
                                let desc = 'Professional fees paid to medical practitioners / consultants';
                                if (rate === 5.0) {
                                    atc = 'WI100';
                                    desc = 'Rentals: On gross rental or lease of real property';
                                } else if (rate === 1.0) {
                                    atc = 'WI152';
                                    desc = 'Income payments to certain contractors';
                                }

                                // Determine Month index (0, 1, 2)
                                let post_date = frappe.datetime.str_to_obj(gl.posting_date);
                                let m = post_date.getMonth() + 1;
                                let month_idx = m - start_month;
                                if (month_idx < 0 || month_idx > 2) month_idx = 0; // fallback

                                if (!grouped_data[atc]) {
                                    grouped_data[atc] = {
                                        desc: desc,
                                        month_1: 0,
                                        month_2: 0,
                                        month_3: 0,
                                        total_income: 0,
                                        tax_withheld: 0
                                    };
                                }

                                // Split income payment base and tax withheld
                                if (month_idx === 0) {
                                    grouped_data[atc].month_1 += inv.net_total || 0;
                                } else if (month_idx === 1) {
                                    grouped_data[atc].month_2 += inv.net_total || 0;
                                } else if (month_idx === 2) {
                                    grouped_data[atc].month_3 += inv.net_total || 0;
                                }

                                grouped_data[atc].total_income += inv.net_total || 0;
                                grouped_data[atc].tax_withheld += amt;
                            }
                        });
                    }

                    frm.clear_table('withholding_details');

                    Object.keys(grouped_data).forEach(atc => {
                        let gd = grouped_data[atc];
                        let row = frm.add_child('withholding_details');
                        row.nature_of_payment = gd.desc;
                        row.atc = atc;
                        row.month_1 = gd.month_1;
                        row.month_2 = gd.month_2;
                        row.month_3 = gd.month_3;
                        row.total_income = gd.total_income;
                        row.tax_withheld = gd.tax_withheld;
                    });

                    frm.refresh_field('withholding_details');
                    frappe.show_alert({message: __('BIR Form 2307 data populated successfully!'), indicator: 'green'});
                }
            });
        });
    }
});

frappe.ui.form.on('BIR General Journal', {
    generate_report: function(frm) {
        if (!frm.doc.company || !frm.doc.from_date || !frm.doc.to_date) {
            frappe.throw(__('Please select Company, From Date, and To Date first.'));
            return;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'GL Entry',
                filters: {
                    company: frm.doc.company,
                    posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]]
                },
                fields: ['posting_date', 'account', 'voucher_type', 'voucher_no', 'debit', 'credit', 'remarks', 'party'],
                limit_page_length: 5000,
                order_by: 'posting_date asc, voucher_no asc, debit desc'
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    frm.clear_table('journal_entries');

                    // Group entries by voucher_no
                    let transactions = [];
                    let last_voucher = null;
                    let current_tx = null;

                    r.message.forEach(entry => {
                        if (entry.voucher_no !== last_voucher) {
                            if (current_tx) {
                                transactions.push(current_tx);
                            }
                            current_tx = {
                                voucher_no: entry.voucher_no,
                                voucher_type: entry.voucher_type,
                                date: entry.posting_date,
                                remarks: entry.remarks || '',
                                postings: []
                            };
                            last_voucher = entry.voucher_no;
                        }
                        current_tx.postings.push(entry);
                    });
                    if (current_tx) {
                        transactions.push(current_tx);
                    }

                    // Collect all invoices for status fetching
                    let purchase_invoices = transactions.filter(t => t.voucher_type === 'Purchase Invoice').map(t => t.voucher_no);
                    let sales_invoices = transactions.filter(t => t.voucher_type === 'Sales Invoice').map(t => t.voucher_no);

                    let invoice_statuses = {};

                    let get_pi_status = function() {
                        return new Promise((resolve) => {
                            if (purchase_invoices.length === 0) return resolve();
                            frappe.call({
                                method: 'frappe.client.get_list',
                                args: {
                                    doctype: 'Purchase Invoice',
                                    filters: { name: ['in', purchase_invoices] },
                                    fields: ['name', 'status']
                                },
                                callback: function(res) {
                                    if (res.message) {
                                        res.message.forEach(d => {
                                            invoice_statuses[d.name] = d.status.toUpperCase();
                                        });
                                    }
                                    resolve();
                                }
                            });
                        });
                    };

                    let get_si_status = function() {
                        return new Promise((resolve) => {
                            if (sales_invoices.length === 0) return resolve();
                            frappe.call({
                                method: 'frappe.client.get_list',
                                args: {
                                    doctype: 'Sales Invoice',
                                    filters: { name: ['in', sales_invoices] },
                                    fields: ['name', 'status']
                                },
                                callback: function(res) {
                                    if (res.message) {
                                        res.message.forEach(d => {
                                            invoice_statuses[d.name] = d.status.toUpperCase();
                                        });
                                    }
                                    resolve();
                                }
                            });
                        });
                    };

                    Promise.all([get_pi_status(), get_si_status()]).then(() => {
                        // Render transactions into the child table
                        transactions.forEach(tx => {
                            let tx_status = invoice_statuses[tx.voucher_no] || 'PAID';

                            tx.postings.forEach((post, index) => {
                                let row = frm.add_child('journal_entries');
                                row.voucher_no = tx.voucher_no;
                                row.voucher_type = tx.voucher_type;

                                // Only the first row of the block gets Date and Status
                                row.date = (index === 0) ? tx.date : '';
                                row.status = (index === 0) ? tx_status : '';

                                // Format Account Code and Name
                                let parts = post.account.split(' - ');
                                row.code = parts[0] || '';
                                row.account_title = parts[1] || '';

                                row.debit = post.debit || 0;
                                row.credit = post.credit || 0;

                                // Indent credit rows
                                row.indent = (post.credit > 0) ? 2 : 1;
                                row.is_explanation_row = 0;
                            });

                            // Add explanation row at the end of the transaction
                            let expl_row = frm.add_child('journal_entries');
                            expl_row.voucher_no = tx.voucher_no;
                            expl_row.voucher_type = tx.voucher_type;
                            expl_row.date = '';
                            expl_row.status = '';
                            expl_row.code = '';
                            expl_row.account_title = '';
                            expl_row.debit = 0;
                            expl_row.credit = 0;

                            // Format explanation (standardize remarks)
                            let short_remarks = tx.remarks.split('\n')[0];
                            expl_row.explanation = short_remarks || `Record transaction (${tx.voucher_type})`;
                            expl_row.is_explanation_row = 1;
                            expl_row.indent = 0;
                        });

                        frm.refresh_field('journal_entries');
                        frappe.show_alert({message: __('Journal generated successfully!'), indicator: 'green'});
                    });
                } else {
                    frappe.msgprint(__('No GL Entries found for this period.'));
                }
            }
        });
    }
});

