                        }
                    });
                } else {
                    frappe.msgprint(__('No Sales Invoices found for this period.'));
                }
            }
        });
    }
});

frappe.ui.form.on('BIR Withholding Summary', {
    generate_report: function(frm) {
        if (!frm.doc.company || !frm.doc.from_date || !frm.doc.to_date) {
            frappe.throw(__('Please select Company, From Date, and To Date first.'));
            return;
        }

        let get_sales = function() {
            return new Promise((resolve) => {
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Sales Invoice',
                        filters: {
                            company: frm.doc.company,
                            posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]],
                            docstatus: 1
                        },
                        fields: ['name', 'posting_date', 'customer', 'customer_name', 'tax_id', 'net_total'],
                        limit_page_length: 5000,
                        order_by: 'posting_date asc, name asc'
                    },
                    callback: function(r) {
                        resolve(r.message || []);
                    }
                });
            });
        };

        let get_purchases = function() {
            return new Promise((resolve) => {
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Purchase Invoice',
                        filters: {
                            company: frm.doc.company,
                            posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]],
                            docstatus: 1
                        },
                        fields: ['name', 'posting_date', 'supplier', 'supplier_name', 'tax_id', 'net_total'],
                        limit_page_length: 5000,
                        order_by: 'posting_date asc, name asc'
                    },
                    callback: function(r) {
                        resolve(r.message || []);
                    }
                });
            });
        };

        Promise.all([get_sales(), get_purchases()]).then(results => {
            let sales_invs = results[0];
            let purchase_invs = results[1];

            let all_names = sales_invs.map(si => si.name).concat(purchase_invs.map(pi => pi.name));

            if (all_names.length === 0) {
                frm.clear_table('withholding_entries');
                frm.refresh_field('withholding_entries');
                frappe.msgprint(__('No Sales or Purchase Invoices found for this period.'));
                return;
            }

            // 2. Fetch GL Entries for Withholding
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'GL Entry',
                    filters: {
                        voucher_no: ['in', all_names]
                    },
                    fields: ['voucher_no', 'account', 'debit', 'credit'],
                    limit_page_length: 5000
                },
                callback: function(gl_res) {
                    let tax_map = {};
                    if (gl_res.message) {
                        gl_res.message.forEach(gl => {
                            let head = (gl.account || '').toLowerCase();
                            if (head.includes('ewt') || head.includes('withholding') || head.includes('creditable') || head.includes('tds')) {
                                if (!tax_map[gl.voucher_no]) {
                                    tax_map[gl.voucher_no] = [];
                                }
                                tax_map[gl.voucher_no].push(gl);
                            }
                        });
                    }

                    frm.clear_table('withholding_entries');

                    let add_entries = function(invoices, is_ap) {
                        invoices.forEach(inv => {
                            let wt_rows = tax_map[inv.name] || [];

                            if (wt_rows.length > 0) {
                                wt_rows.forEach(wt => {
                                    let row = frm.add_child('withholding_entries');
                                    row.document_type = is_ap ? 'A/P Invoice' : 'A/R Invoice';
                                    row.doc_date = inv.posting_date || '';
                                    row.tax_date = inv.posting_date || '';
                                    row.doc_no = inv.name;
                                    row.bp_code = is_ap ? inv.supplier : inv.customer;
                                    row.bp_name = is_ap ? inv.supplier_name : inv.customer_name;
                                    row.tin = inv.tax_id || '';

                                    let code_parts = wt.account.split(' - ');
                                    row.wt_code = code_parts[0] || 'EWT';

                                    let amt = Math.abs((wt.debit || 0) - (wt.credit || 0));
                                    let rate = Math.round((amt / (inv.net_total || 1)) * 100 * 100) / 100;

                                    row.wt_rate = rate;
                                    row.wt_taxable = inv.net_total || 0;
                                    row.wt_amount = amt;
                                    row.status = 'Posted';
                                });
                            } else if (!frm.doc.only_wtax) {
                                let row = frm.add_child('withholding_entries');
                                row.document_type = is_ap ? 'A/P Invoice' : 'A/R Invoice';
                                row.doc_date = inv.posting_date || '';
                                row.tax_date = inv.posting_date || '';
                                row.doc_no = inv.name;
                                row.bp_code = is_ap ? inv.supplier : inv.customer;
                                row.bp_name = is_ap ? inv.supplier_name : inv.customer_name;
                                row.tin = inv.tax_id || '';
                                row.wt_code = '-';
                                row.wt_rate = 0.00;
                                row.wt_taxable = inv.net_total || 0;
                                row.wt_amount = 0.00;
                                row.status = 'Posted';
                            }
                        });
                    };

                    add_entries(sales_invs, false);
                    add_entries(purchase_invs, true);

                    frm.refresh_field('withholding_entries');
                    frappe.show_alert({message: __('Withholding Summary generated successfully!'), indicator: 'green'});
                }
            });
        });
    }
});

frappe.ui.form.on('BIR Cash Disbursement Journal', {
    generate_report: function(frm) {
        if (!frm.doc.company || !frm.doc.from_date || !frm.doc.to_date) {
            frappe.throw(__('Please select Company, From Date, and To Date first.'));
            return;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Purchase Invoice',
                filters: {
                    company: frm.doc.company,
                    posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]],
                    docstatus: 1
                },
                fields: ['name', 'supplier_name', 'posting_date', 'bill_no', 'net_total', 'grand_total', 'outstanding_amount', 'status', 'total_taxes_and_charges', 'taxes_and_charges_deducted', 'tax_id'],
                limit_page_length: 500
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    frm.clear_table('journal_entries');
                    frm.clear_table('account_summary');

                    let total_vatable = 0;
                    let total_input_vat = 0;
                    let total_exempt = 0;
                    let total_zero = 0;
                    let total_grand = 0;
                    let total_ewt = 0;
                    let total_net_paid = 0;

                    r.message.forEach(pi => {
                        let row = frm.add_child('journal_entries');
                        row.date = pi.posting_date || '';
                        row.payee = pi.supplier_name;
                        row.tin = pi.tax_id || '';
                        row.invoice_no = pi.bill_no || pi.name;
                        row.discount_type = 'NONE';
                        row.discount_amount = 0;
                        row.status = pi.status.toUpperCase();

                        let taxes = pi.total_taxes_and_charges || 0;
                        let ewt = pi.taxes_and_charges_deducted || 0;
                        let grand = pi.grand_total || 0;
                        let net_paid = grand - ewt;

                        row.total = grand;
                        row.ewt = ewt;
                        row.net_paid = net_paid;

                        if (taxes > 0) {
                            row.nature = 'VATable Expense';
                            row.vatable = pi.net_total;
                            row.input_vat = taxes;
                            row.exempt = 0;
                            row.zero = 0;

                            total_vatable += pi.net_total;
                            total_input_vat += taxes;
                        } else {
                            row.nature = 'Exempt Expense';
                            row.vatable = 0;
                            row.input_vat = 0;
                            row.exempt = pi.net_total;
                            row.zero = 0;

                            total_exempt += pi.net_total;
                        }

                        total_grand += grand;
                        total_ewt += ewt;
                        total_net_paid += net_paid;
                    });

                    // Add Account Summary Rows
                    let sum1 = frm.add_child('account_summary');
                    sum1.account_title = 'Purchases / Expenses';
                    sum1.debit = total_vatable + total_exempt + total_zero;
                    sum1.credit = 0;

                    let sum2 = frm.add_child('account_summary');
                    sum2.account_title = 'Input VAT';
                    sum2.debit = total_input_vat;
                    sum2.credit = 0;

                    let sum3 = frm.add_child('account_summary');
                    sum3.account_title = 'Cash / Bank';
                    sum3.debit = 0;
                    sum3.credit = total_net_paid;

                    let sum4 = frm.add_child('account_summary');
                    sum4.account_title = 'Creditable Withholding Tax';
                    sum4.debit = 0;
                    sum4.credit = total_ewt;

                    let sum_tot = frm.add_child('account_summary');
                    sum_tot.account_title = 'Total';
                    sum_tot.debit = sum1.debit + sum2.debit;
                    sum_tot.credit = sum3.credit + sum4.credit;

                    frm.refresh_field('journal_entries');
                    frm.refresh_field('account_summary');
                    frappe.show_alert({message: __('Report generated successfully!'), indicator: 'green'});
                } else {
                    frappe.msgprint(__('No submitted Purchase Invoices found for this period.'));
                }
            }
        });
    }
});

frappe.ui.form.on('BIR General Ledger', {
    generate_report: function(frm) {
        if (!frm.doc.company || !frm.doc.from_date || !frm.doc.to_date) {
            frappe.throw(__('Please select Company, From Date, and To Date first.'));
            return;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'GL Entry',
                filters: {
                    company: frm.doc.company,
                    posting_date: ['between', [frm.doc.from_date, frm.doc.to_date]]
                },
                fields: ['posting_date', 'account', 'voucher_type', 'voucher_no', 'debit', 'credit', 'remarks', 'party'],
                limit_page_length: 5000,
                order_by: 'account asc, posting_date asc, name asc'
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    frm.clear_table('gl_entries');

                    // Group entries by account
                    let grouped = {};
                    r.message.forEach(entry => {
                        if (!grouped[entry.account]) {
                            grouped[entry.account] = [];
                        }
                        grouped[entry.account].push(entry);
                    });

                    // Process each account group
                    Object.keys(grouped).sort().forEach(account => {
                        let entries = grouped[account];
                        let running_balance = 0;
                        let total_debit = 0;
                        let total_credit = 0;

                        entries.forEach(entry => {
                            let row = frm.add_child('gl_entries');
                            row.account = account;
                            row.date = entry.posting_date || '';

                            // Format description: VoucherType VoucherNo (Party - Remarks)
                            let party_info = entry.party ? `${entry.party} ` : '';
                            let rem = entry.remarks ? `(${entry.remarks.split('\n')[0]})` : '';
                            row.description = `${entry.voucher_type} ${entry.voucher_no} ${party_info}${rem}`;

                            row.debit = entry.debit || 0;
                            row.credit = entry.credit || 0;

                            running_balance += (entry.debit || 0) - (entry.credit || 0);
                            row.balance = running_balance;
                            row.indent = 1;
                            row.is_total_row = 0;

                            total_debit += (entry.debit || 0);
                            total_credit += (entry.credit || 0);
                        });

                        // Add TOTAL row for the group
                        let total_row = frm.add_child('gl_entries');
                        total_row.account = account;
                        total_row.date = '';
                        total_row.description = ''; // Leave blank for TOTAL label block in print formatting
                        total_row.debit = total_debit;
                        total_row.credit = total_credit;
                        total_row.balance = running_balance;
                        total_row.indent = 2;
                        total_row.is_total_row = 1;
                    });

                    frm.refresh_field('gl_entries');
                    frappe.show_alert({message: __('Ledger generated successfully!'), indicator: 'green'});
                } else {
                    frappe.msgprint(__('No GL Entries found for this period.'));
                }
            }
        });
    }
});

